// Defuzzify
void FunctionBlock_game::defuzzify() {
        double sum_Indice_Popularidade = 0.0;
        double wsum_Indice_Popularidade = 0.0;
        for (int i = 0; i < 1000 ; i++ ) {
                double x = 0.0 + i * 0.1;
                sum_Indice_Popularidade += defuzzify_Indice_Popularidade[i];
                wsum_Indice_Popularidade += x * defuzzify_Indice_Popularidade[i];
        }
        Indice_Popularidade = wsum_Indice_Popularidade / sum_Indice_Popularidade;
}

// Fuzzify all variables
void FunctionBlock_game::fuzzify() {
        Preco_Alto = membership_Preco_Alto(Preco);
        Preco_Baixo = membership_Preco_Baixo(Preco);
        Preco_Medio = membership_Preco_Medio(Preco);
        Preco_MuitoAlto = membership_Preco_MuitoAlto(Preco);
        Preco_MuitoBaixo = membership_Preco_MuitoBaixo(Preco);
        Quantidade_Analises_Positivas_Alta = membership_Quantidade_Analises_Positivas_Alta(Quantidade_Analises_Positivas);
        Quantidade_Analises_Positivas_Baixa = membership_Quantidade_Analises_Positivas_Baixa(Quantidade_Analises_Positivas);
        Quantidade_Analises_Positivas_Media = membership_Quantidade_Analises_Positivas_Media(Quantidade_Analises_Positivas);
        Quantidade_Espectadores_Alta = membership_Quantidade_Espectadores_Alta(Quantidade_Espectadores);
        Quantidade_Espectadores_Baixa = membership_Quantidade_Espectadores_Baixa(Quantidade_Espectadores);
        Quantidade_Espectadores_Media = membership_Quantidade_Espectadores_Media(Quantidade_Espectadores);
}

// Membership functions
double FunctionBlock_game::membership_Indice_Popularidade_Alto(double x) {
        if ( x <= 50.0 )        return 0.0;
        if ( x > 100.0 )        return 1.0;
        if ( x <= 75.0 )        return 0.0 + ( 1.0 - 0.0 ) * ( ( x - 50.0 ) / ( 75.0 - 50.0 ) );     
        if ( x <= 100.0 )       return 1.0 + ( 1.0 - 1.0 ) * ( ( x - 75.0 ) / ( 100.0 - 75.0 ) );    
}

double FunctionBlock_game::membership_Indice_Popularidade_Baixo(double x) {
        if ( x <= 0.0 ) return 1.0;
        if ( x > 50.0 ) return 0.0;
        if ( x <= 25.0 )        return 1.0 + ( 1.0 - 1.0 ) * ( ( x - 0.0 ) / ( 25.0 - 0.0 ) );       
        if ( x <= 50.0 )        return 1.0 + ( 0.0 - 1.0 ) * ( ( x - 25.0 ) / ( 50.0 - 25.0 ) );     
}

