// Print
void FunctionBlock_game::print() {

        cout << "Preco:\t\t\t\t\tR$ " << Preco << " ";
        cout << ((Preco_MuitoBaixo) ? "(Muito Baixo)" : "");
        cout << ((Preco_Baixo) ? "(Baixo)" : "");
        cout << ((Preco_Medio) ? "(Medio)" : "");
        cout << ((Preco_Alto) ? "(Alto)" : "");
        cout << ((Preco_MuitoAlto) ? "(Muito Alto)" : "");
        cout << endl;

        cout << "Quantidade de analises positivas:\t" << Quantidade_Analises_Positivas << " ";
        cout << ((Quantidade_Analises_Positivas_Baixa) ? "(Baixa)" : "");
        cout << ((Quantidade_Analises_Positivas_Media) ? "(Media)" : "");
        cout << ((Quantidade_Analises_Positivas_Alta) ? "(Alta)" : "");
        cout << endl;

        cout << "Quantidade de espectadores diarios:\t" << Quantidade_Espectadores << " ";
        cout << ((Quantidade_Espectadores_Baixa) ? "(Baixa)" : "");
        cout << ((Quantidade_Espectadores_Media) ? "(Media)" : "");
        cout << ((Quantidade_Espectadores_Alta) ? "(Alta)" : "");
        cout << endl << endl;

        cout << "Indice de Popularidade: \t\t" << Indice_Popularidade << "%" << endl << endl;
}

